        "path": "ai-limit-trainer/Program.cs",
        "content": "using System;\nusing System.Collections.Generic;\nusing System.Linq;\nusing System.Threading.Tasks;\nusing AiLimitTrainer.Training;\n\nnamespace AiLimitTrainer\n{\n    /// <summary>\n    /// Main entry point for the AI Limit Trainer application.\n    /// </summary>\n    internal class Program\n    {\n        static async Task Main(string[] args)\n        {\n            Console.WriteLine(\"AI Limit Trainer v1.0\");\n            Console.WriteLine(\"======================\");\n\n            // Default training configuration\n            var config = new TrainingConfiguration\n            {\n                ModelIdentifier = \"gpt-4\",\n                MaxTokens = 4096,\n                Temperature = 0.7f,\n                LearningRate = 0.0001f,\n                BatchSize = 32,\n                Epochs = 10,\n                LimitThreshold = 0.95f\n            };\n\n            // Parse optional command line arguments\n            if (args.Length > 0)\n            {\n                ParseArguments(args, ref config);\n            }\n\n            Console.WriteLine($\"Model: {config.ModelIdentifier}\");\n            Console.WriteLine($\"Max Tokens: {config.MaxTokens}\");\n            Console.WriteLine($\"Temperature: {config.Temperature}\");\n            Console.WriteLine($\"Learning Rate: {config.LearningRate}\");\n            Console.WriteLine($\"Batch Size: {config.BatchSize}\");\n            Console.WriteLine($\"Epochs: {config.Epochs}\");\n            Console.WriteLine($\"Limit Threshold: {config.LimitThreshold}\");\n            Console.WriteLine();\n\n            // Initialize trainer\n            var trainer = new LimitTrainer(config);\n\n            // Generate sample training data (in real scenario, load from file or API)\n            var trainingData = GenerateSampleData(100);\n\n            Console.WriteLine(\"Starting training...\");\n            var result = await trainer.TrainAsync(trainingData);\n\n            Console.WriteLine($\"Training completed: {result.Status}\");\n            Console.WriteLine($\"Final Loss: {result.FinalLoss:F6}\");\n            Console.WriteLine($\"Accuracy: {result.Accuracy:P2}\");\n            Console.WriteLine($\"Limits Reached: {result.LimitsReached}\");\n\n            // Export model limits\n            var exportPath = \"model_limits.json\";\n            await trainer.ExportLimitsAsync(exportPath);\n            Console.WriteLine($\"Limits exported to {exportPath}\");\n        }\n\n        /// <summary>\n        /// Parses command line arguments and updates the configuration.\n        /// </summary>\n        static void ParseArguments(string[] args, ref TrainingConfiguration config)\n        {\n            for (int i = 0; i < args.Length; i++)\n            {\n                switch (args[i].ToLower())\n                {\n                    case \"--model\":\n                        if (i + 1 < args.Length) config.ModelIdentifier = args[++i];\n                        break;\n                    case \"--max-tokens\":\n                        if (i + 1 < args.Length && int.TryParse(args[++i], out int tokens))\n                            config.MaxTokens = tokens;\n                        break;\n                    case \"--temperature\":\n                        if (i + 1 < args.Length && float.TryParse(args[++i], out float temp))\n                            config.Temperature = temp;\n                        break;\n                    case \"--learning-rate\":\n                        if (i + 1 < args.Length && float.TryParse(args[++i], out float lr))\n                            config.LearningRate = lr;\n                        break;\n                    case \"--epochs\":\n                        if (i + 1 < args.Length && int.TryParse(args[++i], out int epochs))\n                            config.Epochs = epochs;\n                        break;\n                    case \"--threshold\":\n                        if (i + 1 < args.Length && float.TryParse(args[++i], out float thresh))\n                            config.LimitThreshold = thresh;\n                        break;\n                    default:\n                        Console.WriteLine($\"Unknown argument: {args[i]}\");\n                        break;\n                }\n            }\n        }\n\n        /// <summary>\n        /// Generates sample training data for demonstration purposes.\n        /// </summary>\n        static List<TrainingSample> GenerateSampleData(int count)\n        {\n            var random = new Random(42);\n            var data = new List<TrainingSample>();\n\n            for (int i = 0; i < count; i++)\n            {\n                data.Add(new TrainingSample\n                {\n                    InputTokens = random.Next(50, 4000),\n                    OutputTokens = random.Next(10, 2000),\n                    Complexity = (float)random.NextDouble(),\n                    DesiredLimit = random.NextDouble() > 0.7f ? 0.9f + (float)random.NextDouble() * 0.1f : 0.5f + (float)random.NextDouble() * 0.4f\n                });\n            }\n\n            return data;\n        }\n    }\n}\n"
