        "path": "ai-limit-trainer/Training/LimitOptimizer.cs",
        "content": "using System;\nusing System.Collections.Generic;\nusing System.Linq;\n\nnamespace AiLimitTrainer.Training\n{\n    /// <summary>\n    /// Advanced optimizer that fine-tunes limits using gradient-based methods.\n    /// </summary>\n    public class LimitOptimizer\n    {\n        private readonly float _learningRate;\n        private readonly float _momentum;\n        private float _previousGradient;\n\n        /// <summary>\n        /// Initializes a new optimizer with given parameters.\n        /// </summary>\n        /// <param name=\"learningRate\">Step size for updates.</param>\n        /// <param name=\"momentum\">Momentum factor (0 to 1).</param>\n        public LimitOptimizer(float learningRate = 0.01f, float momentum = 0.9f)\n        {\n            _learningRate = learningRate;\n            _momentum = Math.Clamp(momentum, 0f, 1f);\n            _previousGradient = 0f;\n        }\n\n        /// <summary>\n        /// Computes the optimal limit adjustment for a batch of samples.\n        /// </summary>\n        /// <param name=\"samples\">Training samples.</param>\n        /// <param name=\"currentLimits\">Current limit values.</param>\n        /// <returns>Adjusted limits.</returns>\n        public float[] Optimize(IEnumerable<TrainingSample> samples, float[] currentLimits)\n        {\n            if (samples == null) throw new ArgumentNullException(nameof(samples));\n            if (currentLimits == null || currentLimits.Length == 0)\n                throw new ArgumentException(\"Current limits cannot be null or empty.\", nameof(currentLimits));\n\n            var sampleList = samples.ToList();\n            if (sampleList.Count == 0)\n                return currentLimits;\n\n            float[] gradients = ComputeGradients(sampleList, currentLimits);\n            float[] adjustedLimits = new float[currentLimits.Length];\n\n            for (int i = 0; i < currentLimits.Length; i++)\n            {\n                // Apply momentum and learning rate\n                float update = _momentum * _previousGradient + _learningRate * gradients[i];\n                _previousGradient = update;\n                adjustedLimits[i] = Math.Clamp(currentLimits[i] - update, 0.1f, 1.0f);\n            }\n\n            return adjustedLimits;\n        }\n\n        /// <summary>\n        /// Computes gradients for each limit dimension.\n        /// </summary>\n        private float[] ComputeGradients(List<TrainingSample> samples, float[] currentLimits)\n        {\n            int limitCount = currentLimits.Length;\n            float[] gradients = new float[limitCount];\n\n            foreach (var sample in samples)\n            {\n                for (int i = 0; i < limitCount; i++)\n                {\n                    // Simplified gradient: difference between predicted and desired\n                    float predicted = PredictFromLimit(sample, currentLimits[i]);\n                    float error = predicted - sample.DesiredLimit;\n                    gradients[i] += 2 * error * sample.Complexity; // derivative of squared error\n                }\n            }\n\n            // Average gradients\n            for (int i = 0; i < limitCount; i++)\n            {\n                gradients[i] /= samples.Count;\n            }\n\n            return gradients;\n        }\n\n        /// <summary>\n        /// Predicts output based on a single limit value.\n        /// </summary>\n        private float PredictFromLimit(TrainingSample sample, float limit)\n        {\n            // Simple linear prediction\n            return limit * sample.Complexity + (1 - limit) * ((float)sample.InputTokens / 4096f);\n        }\n\n        /// <summary>\n        /// Resets the optimizer state (momentum buffer).\n        /// </summary>\n        public void Reset()\n        {\n            _previousGradient = 0f;\n        }\n    }\n}\n"
